#include <stdio.h>
/* ex03：显式链接（FAT）——把 next 指针集中到内存里的 FAT 表
 * 好处：链在内存里走，只有真正读数据块才 I/O，随机访问大幅改善；
 * 代价：整张 FAT 必须常驻内存，磁盘越大 FAT 越大。*/
int main(void) {
    int nblocks = 1000000;     /* 1M 个块 */
    int blk_size = 4096;       /* 4KB/块 */
    int fat_entry = 4;         /* 每个 FAT 项 4 字节 */

    long long disk_bytes = (long long)nblocks * blk_size;
    long long fat_bytes = (long long)nblocks * fat_entry;

    /* 一条 5 块的链：0->7->3->9->END */
    int fat[16] = {7, -1, -1, 9, -1, -1, -1, 3, -1, -2};  /* -2 = 文件结束 */
    printf("FAT 链: ");
    int cur = 0, steps = 0;
    while (cur >= 0) {
        printf("%d%s", cur, fat[cur] == -2 ? "" : " -> ");
        if (fat[cur] == -2) break;
        cur = fat[cur];
        steps++;
    }
    printf("\n沿链在内存中走完，共 %d 步（零磁盘 I/O）\n", steps);

    printf("\n-----------------------------------------------\n");
    printf("磁盘容量      = %lld MB\n", disk_bytes / 1024 / 1024);
    printf("FAT 表大小    = %lld KB (%.2f%% 的磁盘)\n", fat_bytes / 1024,
           100.0 * fat_bytes / disk_bytes);
    printf("若块大小改成 512B，FAT 会变成 %.1f MB —— 这就是 FAT32 为什么限制分区大小\n",
           (double)nblocks * 8 * fat_entry / 1024 / 1024);
    return 0;
}
